pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Non-owner attempts to call sendMoney with 1 ether, empty data
        address nonOwner = address(0x1234);
        vm.deal(address(c), 1 ether); // fund contract so it has balance if needed
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney{value: 1 ether}(address(0x5678), 1 ether, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference: call reverts (ok false), depositsCount remains 0.
        // In buggy: call succeeds (ok true), depositsCount becomes 1.
        assertTrue(ok == true); // bug: ok is true; reference: ok is false -> assertion fails on reference? Wait, need assertion that reference holds and bug breaks.
