contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        // Give nonOwner some ether to pay for gas, but sendMoney value is 0
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        try c.sendMoney(nonOwner, 0, hex"00") {
            // Reference should revert, buggy should succeed
        } catch { }
        // After call, owner withdraws all
        vm.prank(c.owner());
        c.withdrawAll();
        // In reference, sendMoney reverted => balance 0; buggy sendMoney succeeded => balance 0 anyway (value 0, no transfer)
        // But buggy increments depositsCount, though not directly observable. However, owner's withdrawal succeeded in both.
        // Actually, we need a difference that is observable. Since sendMoney with value 0 changes nothing else, let's use depositsCount:
        // Reference: depositsCount stays 0; buggy: depositsCount = 1
        bool refBehavior = (c.depositsCount() == 0);
        assertTrue(refBehavior == false); // False here means test fails on reference? Wait, we want test passes on reference, fails on buggy.
        // Actually reference has depositsCount=0, so refBehavior=true. We assert true, so test passes on reference. On buggy, depositsCount=1, refBehavior=false, so assert fails.
        assertTrue(c.depositsCount() == 0);
    }
}

