pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract RejectEther {
    // No fallback or receive function – cannot receive ether
}

contract InvMutTest is Test {
    C c;
    RejectEther target;

    function setUp() public {
        c = new C();
        target = new RejectEther();
    }

    function testRegression_property() public {
        address owner = c.owner();
        vm.deal(owner, 5 ether);
        vm.prank(owner);
        (bool ok,) = address(c).call{value: 5 ether}("");
        assertTrue(ok, "funding failed");

        uint256 balanceBefore = address(c).balance;

        vm.prank(owner);
        try c.sendMoney(address(target), 1 ether, "") {
            // In the bug, the call returns true even though target cannot receive ether
            // In the reference, this path is never reached (revert)
        } catch {
            // The reference reverts here – ok
        }

        // After the call, the reference reverts before sending, so balance unchanged.
        // The bug fails to revert, so the 1 ether is actually sent (lost to target? No, target has no fallback – it will be lost/stuck but balanceOf(c) decreases)
        // Actually, when target.call fails, the bug doesn't revert, so the ether stays in c? Wait: call{value:1 ether} reverts on recipient failure? No, call returns false but the ether is consumed from c's balance.
        // So the bug sends 1 ether, it gets returned? No, on failed call the ether is returned to the sender (c). So c's balance remains unchanged. Hmm.
        // Let's rethink: For a call that sends value, if the recipient has no payable fallback/receive, the call returns false but the value is NOT transferred – it remains in the caller c. So the bug would keep c's balance unchanged too.
        // This approach won't produce the divergence described.
        // Better: make the target revert in receive, so call fails, but bug doesn't revert – yet c's balance is unchanged because transfer didn't happen.
        // The divergence must be in a revert vs no-revert observable state change.
        // Let's use a target that succeeds but we check a state variable of c that only changes on success.
        // Actually the given difference is only about revert vs no revert, not balance. So use assertTrue that the call didn't revert in the bug but did in reference.
        bool didNotRevert;
        vm.prank(owner);
        try c.sendMoney(address(target), 1 ether, "") {
            didNotRevert = true;
        } catch {
            didNotRevert = false;
        }
        // But both reference and bug might have different didNotRevert values – that is the observation.
        // However in the reference the call reverts, didNotRevert=false; in the bug it succeeds, didNotRevert=true.
        // So we can assertTrue(!didNotRevert) – but that would pass on reference and fail on bug.
        // But the problem says "assertTrue(<concrete fact reading c>)" – the fact must be reading c's public surface.
        // We can read address(c).balance – but that doesn't change. Alternatively, we can read depositsCount if the fallback is used.
        // Better: Let the target be a contract that has a fallback but reverts to cause the call to fail.
        // Then in the bug, the call returns false but doesn't revert, so depositsCount is updated because fallback reverts? No, if fallback reverts, call fails and depositsCount is not incremented because the fallback didn't complete.
        // So no change to depositsCount.
        // The only observable difference is the revert itself. So assert over a try/catch flag.
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a receiver contract with a payable fallback that uses all gas
        Receiver receiver = new Receiver();
        vm.deal(address(this), 1 ether);
        vm.prank(c.owner());
        // Fund the contract
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent);
        uint256 balanceBefore = address(c).balance;
        // Call sendMoney with very low gas to cause failure
        (bool ok, ) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.sendMoney.selector, address(receiver), 0.5 ether, ""));
        uint256 balanceAfter = address(c).balance;
        // Reference: revert on failure → balance unchanged; bug: no revert → balance decreased
        assertTrue(balanceAfter == balanceBefore);
    }
}

contract Receiver {
    fallback() external payable { 
        // Intentionally expensive loop to consume gas
        for(uint256 i = 0; i < 1000000; i++) {}
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Helper contract that cannot receive ether (no payable fallback/receive)
    contract NonPayable {
        function doNothing() external {}
    }

    function setUp() public { c = new C(); }

    function testRegression_property() public {
        NonPayable target = new NonPayable();
        address owner = address(this);

        // Fund c with 1 ether
        vm.deal(address(c), 1 ether);

        // Owner calls sendMoney to transfer 1 ether to non-payable target
        bytes memory emptyData = "";
        bool ok;
        try c.sendMoney(address(target), 1 ether, emptyData) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference reverts (ok = false), bug does not (ok = true)
        // So bug leaves c.balance = 0, reference leaves c.balance = 1 ether
        assertTrue(ok == false, "sendMoney should have reverted but did not");
        assertEq(address(c).balance, 1 ether, "c.balance should still be 1 ether after revert");
    }
}
